/* @lc app=leetcode id=3454 lang=kotlin */ class Solution { fun up(cnt: IntArray, len: LongArray, xs: List<Int>, o: Int, l: Int, r: Int, a: Int, b: Int, d: Int): Unit = if (a > r || b < l) Unit else (if (a <= l && r <= b) cnt.set(o, cnt[o] + d) else ((l + r) / 2).let { m -> up(cnt, len, xs, 2 * o, l, m, a, b, d).also { up(cnt, len, xs, 2 * o + 1, m + 1, r, a, b, d) } }).let { len.set(o, if (cnt[o] > 0) (xs[r + 1] - xs[l]).toLong() else if (l == r) 0L else len[2 * o] + len[2 * o + 1]) } fun separateSquares(squares: Array<IntArray>): Double = squares.flatMap { listOf(it[0], it[0] + it[2]) }.distinct().sorted().let { xs -> (xs.size - 1).let { m -> IntArray(4 * m).let { cnt -> LongArray(4 * m).let { len -> squares.flatMap { s -> listOf(Triple(s[1], s, 1), Triple(s[1] + s[2], s, -1)) }.groupBy { it.first }.toSortedMap().entries.fold(Pair(null as Int?, ArrayList<Triple<Int, Int, Long>>())) { (py, segs), (y, evs) -> segs.apply { if (py != null) add(Triple(py, y, len[1])) }.also { evs.forEach { (_, s, d) -> up(cnt, len, xs, 1, 0, m - 1, xs.binarySearch(s[0]), xs.binarySearch(s[0] + s[2]) - 1, d) } }.let { y to it } }.second.let { segs -> segs.sumOf { (a, b, w) -> w * (b - a) }.let { T -> segs.fold(0L to -1.0) { (cum, ans), (a, b, w) -> if (ans >= 0) cum to ans else (cum + w * (b - a)).let { c2 -> if (2 * c2 >= T) c2 to a + (T / 2.0 - cum) / w else c2 to -1.0 } }.second } } } } } } }